#include "reward_planner.h"
#include "wallet_fixtures.h"
#include <iostream>
#include <util/translation.h>
const TranslateFn G_TRANSLATION_FUN{nullptr};
using namespace mercaweave;using namespace mercaweave::reward_research;
namespace wt=mercaweave::wallet_research::test;
namespace {
size_t checks=0;void Check(bool b,const char* m){++checks;if(!b)throw std::runtime_error(m);}
struct Fixture {
    std::unique_ptr<Wallet> w=wt::Owner();integration::ViewPtr view=integration::View::Create(wt::Genesis());
    Address mining=w->Issue(0,2),destination=w->Issue(7,0,2);std::vector<FundingCoin> coins;Policy policy;Planner planner;
    explicit Fixture(size_t count=50){policy.enabled=policy.opted_in=policy.isolated=policy.network=policy.loaded=policy.synchronized=policy.signer=true;policy.destination=destination.script;policy.revision=1;Add(count);}
    void Add(size_t n,int height=1,const Address* owner=nullptr,CAmount value=10000){for(size_t i=0;i<n;++i){auto point=wt::Point(static_cast<uint32_t>(coins.size()+1));view->Insert(point,Coin{CTxOut{value,owner?owner->script:mining.script},height,true});coins.push_back({point});}}
    Decision Eval(){return planner.Evaluate(*w,view,coins,policy);}
};
void Run()
{
    for(size_t n:{size_t(0),size_t(1),size_t(49),size_t(50),size_t(51)}){Fixture f(n);auto r=f.Eval();Check(r.mature==n&&r.block==(n<50?Block::Threshold:Block::None),"mature trigger 0/1/49/50/51");if(r.proposal)Check(r.proposal->inputs.size()==n&&r.proposal->transactions.size()==1&&r.proposal->transactions[0].groups==1,"same reward address shares one exact key");}
    Fixture f;auto first=f.Eval();auto id=first.proposal->id;Check(f.Eval().reused&&f.Eval().proposal->id==id,"idempotent scheduling reserves one proposal");std::reverse(f.coins.begin(),f.coins.end());Check(f.Eval().proposal->id==id,"deterministic candidate ordering");
    auto psbt=first.proposal->transactions[0].psbt;Check(f.planner.Attach(f.view,wt::Genesis(),std::span(&psbt,1))==Block::Partial,"unsigned PSBT remains partial");Check(f.Eval().block==Block::Partial,"partial scheduler state retained");
    auto wrong=psbt;wrong.tx->vout[0].nValue--;Check(f.planner.Attach(f.view,wt::Genesis(),std::span(&wrong,1))==Block::Stale,"changed destination/value body cannot attach");
    auto signed_progress=GroupPSBT::Sign(psbt,*f.w,f.view,wt::ZeroFixture());Check(signed_progress.group_signatures==1&&signed_progress.native_signatures==0,"explicit signer uses one genuine group signature");GroupPSBT::FinalizeAvailable(psbt,f.view,wt::Genesis());Check(f.planner.Attach(f.view,wt::Genesis(),std::span(&psbt,1))==Block::None&&f.planner.Pending()->phase==Phase::Verified,"complete proposal validates through WO04");
    f.planner.Cancel();Check(!f.planner.Pending()&&f.Eval().block==Block::Cancelled,"cancel releases reservation and suppresses same trigger");++f.policy.revision;Check(f.Eval().block==Block::None,"explicit revised policy can retry");f.planner.Conflict(true);Check(f.Eval().block==Block::Conflict,"replacement prevents duplicate proposal");++f.policy.revision;f.Eval();f.planner.Fail();Check(f.Eval().block==Block::Failed,"failed signing/proposal is not retried blindly");++f.policy.revision;f.Eval();f.planner.Unload();Check(f.Eval().block==Block::Unloaded&&!f.planner.Pending(),"unload is terminal for this scheduler owner");
    Fixture maturity(49);maturity.Add(1,199);auto mixed=maturity.Eval();Check(mixed.block==Block::Threshold&&mixed.mature==49&&mixed.immature==1,"immature coinbase excluded");auto immature=maturity.coins.back().point;maturity.view->Insert(immature,Coin{CTxOut{10000,maturity.mining.script},1,true},true);Check(maturity.Eval().block==Block::None,"fresh maturity view can plan");maturity.policy.reorganizing=true;Check(maturity.Eval().block==Block::Reorg&&!maturity.planner.Pending(),"reorg pauses and releases proposal");maturity.policy.reorganizing=false;maturity.view->Insert(immature,Coin{CTxOut{10000,maturity.mining.script},199,true},true);Check(maturity.Eval().block==Block::Threshold,"reorg maturity rollback enforced");
    Fixture split(25);split.w->Rotate(0,2);auto second=split.w->Issue(0,2);split.Add(25,1,&second);Check(split.Eval().block==Block::Threshold,"25 plus 25 independent keys do not meet per-key threshold");split.Add(25);auto exact=split.Eval();Check(exact.block==Block::None&&exact.proposal->inputs.size()==50&&exact.proposal->key==split.mining.pk,"independent keys never aggregate");split.policy.selected=second.pk;Check(split.Eval().block==Block::Threshold,"explicit exact group selection respected");
    Fixture policy;policy.policy.enabled=false;Check(policy.Eval().block==Block::Disabled,"automatic sweeps disabled");policy.policy.enabled=true;policy.policy.opted_in=false;Check(policy.Eval().block==Block::Disabled,"explicit opt-in required");policy.policy.opted_in=true;policy.policy.network=false;Check(policy.Eval().block==Block::Network,"unavailable network pauses");policy.policy.network=true;policy.policy.isolated=false;Check(policy.Eval().block==Block::Network,"no non-isolated authorization");policy.policy.isolated=true;policy.policy.synchronized=false;Check(policy.Eval().block==Block::Sync,"unsynchronized state pauses");policy.policy.synchronized=true;policy.policy.signer=false;Check(policy.Eval().block==Block::Signer,"signer missing");policy.policy.signer=true;policy.w->Lock();Check(policy.Eval().block==Block::Locked&&policy.w->IsLocked(),"no silent unlock");Check(policy.w->Unlock(SecureString{"public research fixture"}),"explicit fixture unlock");
    policy.policy.destination=policy.mining.script;Check(policy.Eval().block==Block::Destination,"grouped destination rejected");policy.policy.destination=CScript{}<<OP_TRUE;Check(policy.Eval().block==Block::Destination,"malformed destination rejected");policy.policy.destination=policy.destination.script;policy.policy.fee.maximum=1;Check(policy.Eval().block==Block::Fee,"fee ceiling enforced");policy.policy.fee.maximum=1000;policy.policy.external_reservations.insert(policy.coins[0].point);Check(policy.Eval().block==Block::Reserved,"externally reserved input cannot be selected");policy.policy.external_reservations.clear();policy.coins.push_back(policy.coins[0]);Check(policy.Eval().block==Block::Metadata,"duplicate candidates fail closed");policy.coins.pop_back();policy.policy.threshold=51;Check(policy.Eval().block==Block::Threshold,"configurable trigger");policy.policy.threshold=49;Check(policy.Eval().block==Block::None,"configured lower trigger accepted");
    auto prior=policy.planner.Pending()->id;policy.policy.fee.per_k=2;auto fee_changed=policy.Eval();Check(fee_changed.block==Block::None&&fee_changed.proposal->id!=prior,"changed fees retire old proposal");prior=fee_changed.proposal->id;auto other=policy.w->Issue(8,0,2);policy.policy.destination=other.script;Check(policy.Eval().proposal->id!=prior,"changed destination retires proposal");policy.view->Spend(policy.coins[0].point);auto balance=policy.Eval();Check(balance.proposal&&balance.proposal->inputs.size()==49,"spent/conflicted balance is reacquired");
    Fixture dust(0);dust.Add(1,1,nullptr,7);dust.policy.threshold=1;Check(dust.Eval().block==Block::Dust,"fee output below two-unit dust floor blocked");Fixture funds(0);funds.Add(1,1,nullptr,1);funds.policy.threshold=1;Check(funds.Eval().block==Block::Funds,"insufficient reward value blocked");
    Fixture limits(1025);auto batches=limits.Eval();Check(batches.block==Block::None&&batches.proposal->transactions.size()==2,"1025 same-key rewards split at member limit");size_t total=0;for(const auto& tx:batches.proposal->transactions){Check(tx.selected<=1024&&tx.sizes.weight<=400000&&tx.groups==1,"strict transaction resource bounds");total+=tx.selected;}Check(total==1025,"split workflow preserves all eligible rewards");
    Fixture height(1);height.policy.threshold=1;height.policy.spend_height=350;height.view->Insert(height.coins[0].point,Coin{CTxOut{10000,height.mining.script},250,true},true);auto at_height=height.Eval();Check(at_height.block==Block::None,"WO05 estimator accepts authenticated caller spend height");auto height_psbt=at_height.proposal->transactions[0].psbt;GroupPSBT::Sign(height_psbt,*height.w,height.view,wt::ZeroFixture(),350);Check(height.planner.Attach(height.view,wt::Genesis(),std::span(&height_psbt,1),350)==Block::None,"height binds final authoritative validation");
}
}
int main(){try{Run();std::cout<<"{\"reward_checks\":"<<checks<<",\"passed\":true}\n";}catch(const std::exception& e){std::cerr<<"FAIL reward planner: "<<e.what()<<'\n';return 1;}}
